/**
 * Copies the shared core modules and the active dataset into the web app's
 * public folder so the PWA is fully self-contained and works offline with no
 * build tooling. Run this whenever the core or the dataset changes.
 */

import { readFile, writeFile, mkdir, copyFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = resolve(__dirname, '../../..');

const coreSrc = join(root, 'packages/core/src');
const outCore = join(__dirname, '../public/vendor/core');
const dataPath = join(root, 'data/sample.json');
const outData = join(__dirname, '../public/data.js');

const CORE_FILES = [
  'severity.js',
  'normalize.js',
  'validate.js',
  'engine.js',
  'index.js',
];

async function main() {
  await mkdir(outCore, { recursive: true });
  for (const file of CORE_FILES) {
    await copyFile(join(coreSrc, file), join(outCore, file));
  }

  const dataset = JSON.parse(await readFile(dataPath, 'utf8'));
  const banner =
    '// AUTO-GENERATED by scripts/bundle-data.js — edit data/sample.json instead.\n';
  await writeFile(
    outData,
    `${banner}export const dataset = ${JSON.stringify(dataset, null, 2)};\n`
  );

  console.log(`Bundled ${CORE_FILES.length} core modules and the dataset.`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
